#include "ksNativeParameterSupportService.h"
#include "ksNativeParameterSupportAbi.h"
#include <array>
#include <vector>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <new>
#include <stdexcept>
namespace{bool tracking=false;uint64_t allocations=0;}
void*operator new(std::size_t n){if(tracking)++allocations;if(auto*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}void*operator new[](std::size_t n){return::operator new(n);}void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete(void*p,std::size_t)noexcept{std::free(p);}void operator delete[](void*p,std::size_t)noexcept{std::free(p);}
void check(bool v,const char*m){if(!v)throw std::runtime_error(m);}
int main(){try{using T=ks::NativeParameterSupportService;using K=T::Kind;std::vector<uint8_t>m(1<<24);uint64_t graphs=0,phases=0,rejects=0,reads=0,writes=0;uint32_t components=0;
for(unsigned kind=0;kind<6;++kind)for(unsigned key=0;key<256;++key)for(unsigned mode:{0u,1u}){std::fill(m.begin()+0xb8e8,m.begin()+0x30000,uint8_t(0));const auto wide=[&](unsigned a,uint32_t v){for(unsigned n=0;n<4;++n)m[a+n]=uint8_t(v>>(24-8*n));};wide(0x167bc,0x18000);wide(0x167c0,0x19000);m[0x17526]=uint8_t(key);m[0x167ba]=uint8_t(mode);m[0x1679a]=uint8_t(key^171);m[0x158f2]=uint8_t(key%5);m[0x1678d]=99;for(unsigned i=0;i<256;++i)m[0x18000+i]=uint8_t(key+i);for(unsigned d=0;d<4;++d){wide(72134+4*d,0x12000+256*d);const unsigned desc=0x12000+256*d;m[desc]=d;m[desc+1]=64;m[desc+2]=3;m[desc+3]=0;for(unsigned i=4;i<256;i+=2){m[desc+i]=uint8_t(i%8);m[desc+i+1]=uint8_t(i/2);}}
unsigned count=0;int previous=-1;tracking=true;{T t(K(kind),{uint8_t(key),uint8_t(key^99),uint8_t(key),0x12345678,0x18000,0x19000});while(!t.complete()){struct Unowned{};check(!t.task<Unowned>(),"Unknown support task query");const auto cost=t.nextClocks(previous);check(cost>0,"Support pure stalled");std::array<unsigned char,sizeof(T)>saved{};std::memcpy(saved.data(),&t,sizeof(T));unsigned callbacks=0;check(t.advanceBefore(cost-1,[&](uint32_t,unsigned){++callbacks;return uint8_t(0);},[&](uint32_t,uint8_t,unsigned){++callbacks;},previous)==0&&!callbacks&&!std::memcmp(saved.data(),&t,sizeof(T)),"Support budget changed object");++rejects;const auto read=[&](uint32_t a,unsigned dt){check(a<(1u<<24)&&dt<=cost,"Support pure read bound");++reads;return m[a];};const auto write=[&](uint32_t a,uint8_t v,unsigned dt){check(a<(1u<<24)&&dt<=cost&&!(a>=0xfff000&&a<0xfffc00),"Support pure write bound");++writes;m[a]=v;previous=int(a);};check(t.advanceBefore(cost,read,write,previous)==cost,"Support pure admission");if(t.effect().write)previous=-1;check(++count<16384,"Support pure did not complete");++phases;}
check(!t.task<ks::StateStorageTask>()&&!t.task<ks::StateFieldMapTask>()&&!t.task<ks::StateParameterExpandTask>()&&!t.task<ks::StatePanelModesTask>(),"Completed support task selector");const auto&s=t.summary();if(kind==0)check(s.map->outcome()==ks::StateFieldMapTask::Outcome::Unmapped||key>=104&&key<=107,"Map scalar domain");if(kind==1||kind==2){if(kind==2||mode){uint32_t current=0,live=0;for(unsigned n=0;n<4;++n){current=(current<<8)|m[0x167bc+n];live=(live<<8)|m[0x167c0+n];}check(current==0x168fcu+256*key&&live==0x16e12u+256*key,"Bind scalar base oracle");}}if(kind==3)check(m[0x1679a]==uint8_t((key^171)|(1u<<(key&7))),"Dirty scalar oracle");if(kind>=4){const auto target=kind==4?0x19000u:0x19000u;check(m[target+214]==uint8_t((key+88)&3),"Expand lowbits oracle");check(m[target+227]==uint8_t(int8_t(uint8_t((key+126)<<1))>>4),"Expand signed oracle");}struct A{std::array<uint32_t,7>values{};uint8_t flags=0;};A a;projectNativeParameterSupport(a,t);components|=t.components();}tracking=false;++graphs;}
check(components==15&&!allocations,"Support pure coverage/heap");std::cout<<"PASS Pure NativeParameterSupport graphs="<<graphs<<" phases="<<phases<<" whole_object_budget_rejects="<<rejects<<" reads="<<reads<<" writes="<<writes<<" components="<<components<<" sizeof="<<sizeof(T)<<" allocations="<<allocations<<'\n';return 0;
}catch(const std::exception&e){tracking=false;std::cerr<<e.what()<<'\n';return 1;}}
